(function () {

const XZ_BUILD = '1.0.0';
if (window.__XZ_RUNNING__ === XZ_BUILD) return;
window.__XZ_RUNNING__ = XZ_BUILD;

const D = (function () { try { return window.parent.document || document; } catch (e) { return document; } })();
const W = (function () { try { return window.parent || window; } catch (e) { return window; } })();

const H = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const num = (v, d) => { const t = String(v == null ? '' : v).trim().replace(/^\+/, ''); const n = t === '' ? NaN : Number(t); return Number.isFinite(n) ? n : (d || 0); };
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const clean = s => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, 240);
const pct = (a, b) => b > 0 ? clamp(Math.round(a / b * 100), 0, 100) : 0;
const fmtS = v => (v >= 0 ? '+' : '') + v;

const LIFE = ['学识', '口才', '魅力', '人脉', '胆识', '手艺'];
const BATK = ['力量', '敏捷', '体质', '神识'];
const ROOTS = ['未觉醒（剧情决定）', '伪灵根', '杂灵根', '双灵根', '单灵根', '天灵根', '特殊体质'];
const SCHOOLS = [
  { k: '炼丹', d: '药草入炉，疗伤增益，丹毒是代价' },
  { k: '画符', d: '符箓速成，耗灵低，最适合末法' },
  { k: '阵法', d: '布阵守地困敌，前期准备成本高' },
  { k: '邪术', d: '血祭夺舍等禁术，威力大，业力反噬' },
  { k: '御鬼', d: '收小鬼为仆，养鬼耗阴气，鬼仆会成长' },
  { k: '出马', d: '请仙家上身或供奉，仙家有脾气，香火是纽带' },
  { k: '卜算', d: '推演吉凶，窥天机有代价' },
  { k: '炼器', d: '打造法器，看材料与火候' }
];
const CN = ['一', '二', '三', '四', '五', '六', '七', '八', '九', '十', '十一', '十二'];
const REALMS = ['凡人'].concat(CN.map(n => '炼气' + n + '层'), ['筑基初期', '筑基中期', '筑基后期', '金丹初期', '金丹中期', '金丹后期', '元婴初期', '元婴中期', '元婴后期', '化神']);
const RANKS = ['凡品', '下品', '中品', '上品', '极品', '仙品'];
const RANK_COLOR = { '凡品': '#b9b6ad', '下品': '#7fcf8a', '中品': '#6aa9ff', '上品': '#b58bff', '极品': '#ffb454', '仙品': '#ff6f8e' };
const ITEM_TYPES = ['丹药', '符箓', '法器', '材料', '鬼物', '书籍', '杂物'];
const ORG_KINDS = ['官方', '道门', '散修', '世家', '商会', '邪道', '民间', '鬼市', '妖族', '其他'];
const ALLY_KINDS = ['小鬼', '仙家', '式神', '灵宠', '其他'];
const MERIT_T = [[30, '积善之人'], [100, '一方善士'], [300, '功德在身'], [800, '金光护体']];
const KARMA_T = [[30, '业障缠身'], [100, '邪名在外'], [300, '血债累累'], [800, '煞星']];
const AURA_T = [
  [10, '末法：灵气稀薄如被稀释百倍的茶，修炼近乎停滞，术法消耗肉眼可见'],
  [25, '余烬：个别灵脉遗址与古地偶有灵气涌动，低阶修士察觉异样，普通人只觉得天气怪'],
  [50, '初醒：灵气在多处渗出，低阶鬼物苏醒，灵材重新生长，开始有凡人出现异象'],
  [75, '复苏：灵气明显回升，修炼速度翻倍，妖兽化形增多，世俗界难以再完全掩盖'],
  [101, '潮涌：灵气汹涌，异象频发，大妖与厉鬼出世，世俗秩序受到冲击']
];
const DAY_STEP_MAX = 30;

const PLOT = [
  {
    name: '余烬', need: 2,
    control: '只描写零星灵气异动、异常地点和灵材价格变化。不得说明异动来自阵眼，也不得说明存在九处阵眼。',
    clues: {
      C1A: '一处不该有灵气的地方出现了灵气：枯死多年的古树抽芽、废井冒出带灵气的白雾，普通人只当成怪事。',
      C1B: '低阶鬼物的活动明显增多，且不再只依附原来的地点，有鬼物在往同一个方向聚集。',
      C1C: '有人在悄悄高价收购古阵残件、阵石与老地基图纸，出手阔绰，来路不明。'
    }
  },
  {
    name: '暗流', need: 2,
    control: '只通过阵材收购、失踪、地标异常和势力态度变化埋线。不得直接说明这些行动由沈宴一系统一负责。',
    clues: {
      C2A: '收购与清理的指令出自同一条线：地下世界的二号人物「蛇」，而不是名义上的首领。',
      C2B: '数座城市的老城区里，同一类地标（古桥、旧祠、老井、石碑）被人动过手脚，或正被人盯着。',
      C2C: '有修士因为靠近这些地标而失踪或疯癫，官方与道门内部对此讳莫如深。'
    }
  },
  {
    name: '阵眼', need: 2,
    control: '允许出现残缺古籍、守阵传承、灵气封锁和古城异常，但只能给出局部证据。不得一次性解释锁灵大阵、九处阵眼和清衡门的完整关系。',
    clues: {
      C3A: '一份残破古籍或碑文记载了「九眼锁灵」：末法是人为封锁，而非天道轮转。',
      C3B: '一处阵眼被破后的真实后果：灵气复苏的同时，厉鬼出世、妖兽狂化、凡人出现失控异象。',
      C3C: '清衡门与另外几个已断绝的门派曾各守一处阵眼，守阵的传承正在一支支消失。'
    }
  },
  {
    name: '钥匙', need: 2,
    control: '只描写沈宴让狼出席关键地点、狼身上的异常烙印和天珩的隐瞒。不得直接说明狼是钥匙、沈宴要开启总阵眼或前任门主的真实安排。',
    clues: {
      C4A: '沈宴多次要求狼现身某些关键地点，只让他“在场”，从不解释理由。',
      C4B: '狼身上有一枚连他自己都不理解的传承烙印，只有守阵一脉的人认得。',
      C4C: '前任门主当年把狼送入天珩门下，用意不是传承道统，而是为总阵眼预备一把钥匙。'
    }
  },
  {
    name: '抉择', need: 99,
    control: '只在玩家已经掌握足够证据并主动接近终局时，描写各方准备、风险和可选择的方向。不得提前宣布总阵眼即将开启，也不得替玩家决定最终立场。',
    clues: {
      C5A: '总阵眼开启的时间与地点。',
      C5B: '各方势力在总阵眼周围的布置与底线。'
    }
  }
];

const rankIdx = r => RANKS.indexOf(r);
const realmIdx = r => Math.max(0, REALMS.indexOf(r));
const hpOf = i => 100 + i * 40;
const mpOf = i => 10 + i * 25;
const stanceOf = v => v <= -60 ? '敌对' : v <= -20 ? '警戒' : v < 20 ? '中立' : v < 60 ? '友好' : '同盟';
const gradeOf = lv => lv >= 80 ? '大成' : lv >= 60 ? '精通' : lv >= 40 ? '熟练' : lv >= 20 ? '初窥' : '入门';
const auraText = v => (AURA_T.find(x => v < x[0]) || AURA_T[AURA_T.length - 1])[1];
const normClue = v => clean(v).toUpperCase().replace(/[^A-Z0-9]/g, '');
const clueStage = id => Number(String(id).charAt(1)) || 0;
const clueText = id => { const p = PLOT[clueStage(id) - 1]; return p && p.clues[id] ? p.clues[id] : ''; };

function guessType(name) {
  if (/丹|药|散|膏/.test(name)) return '丹药';
  if (/符|箓/.test(name)) return '符箓';
  if (/剑|镜|铃|印|幡|器|珠|佩|罗盘|钟/.test(name)) return '法器';
  if (/书|经|谱|录|卷|册/.test(name)) return '书籍';
  if (/魂|瓮|鬼/.test(name)) return '鬼物';
  if (/草|石|矿|血|骨|木|粉|砂|玉/.test(name)) return '材料';
  return '杂物';
}

function blank() {
  return { ver: 1, made: false, p: null, cities: {}, orgs: {}, npcs: {}, allies: [], fame: { merit: 0, karma: 0 }, clues: [], stage: 1, aura: 5, day: 1, notes: [], processed: {} };
}

function norm(r) {
  const b = blank();
  if (!r || typeof r !== 'object') return b;
  Object.keys(b).forEach(k => { if (r[k] === undefined) r[k] = b[k]; });
  r.fame = Object.assign({ merit: 0, karma: 0 }, r.fame || {});
  r.stage = clamp(Math.round(num(r.stage, 1)), 1, 5);
  r.day = Math.max(1, Math.round(num(r.day, 1)));
  r.aura = clamp(Math.round(num(r.aura, 5)), 0, 100);
  if (!Array.isArray(r.clues)) r.clues = [];
  if (!Array.isArray(r.notes)) r.notes = [];
  if (!Array.isArray(r.allies)) r.allies = [];
  if (r.p) {
    const p = r.p;
    p.bag = Array.isArray(p.bag) ? p.bag : [];
    p.buffs = Array.isArray(p.buffs) ? p.buffs : [];
    p.titles = Array.isArray(p.titles) ? p.titles : [];
    p.schools = Array.isArray(p.schools) ? p.schools : [];
    p.life = Object.assign({}, p.life || {});
    p.bat = Object.assign({}, p.bat || {});
    LIFE.forEach(k => { p.life[k] = clamp(Math.round(num(p.life[k], 10)), 0, 100); });
    BATK.forEach(k => { p.bat[k] = clamp(Math.round(num(p.bat[k], 10)), 0, 100); });
    const i = realmIdx(p.realm);
    p.hpMax = hpOf(i); p.mpMax = mpOf(i);
    p.hp = clamp(Math.round(num(p.hp, p.hpMax)), 0, p.hpMax);
    p.mp = clamp(Math.round(num(p.mp, p.mpMax)), 0, p.mpMax);
    p.cash = Math.max(0, Math.round(num(p.cash, 0)));
    p.stone = Math.max(0, Math.round(num(p.stone, 0)));
  }
  return r;
}

let root = blank();

function load() {
  let chatOk = false;
  try { const v = getVariables({ type: 'chat' }); if (v && typeof v === 'object') { chatOk = true; if (v.XZ) { root = norm(v.XZ); return root; } } } catch (e) { console.warn('[XZ] load-chat err:', e); }
  if (!chatOk) { try { const v = getVariables() || {}; if (v && v.__XZ__) { root = norm(v.__XZ__); return root; } } catch (e) { console.warn('[XZ] load-global err:', e); } }
  root = blank();
  return root;
}

async function save(scan) {
  const dg = digest(root, scan || '');
  const snap = JSON.parse(JSON.stringify(root));
  let chatOk = false;
  try {
    const a = getVariables({ type: 'chat' }) || {};
    a.XZ = snap; a.XZ_digest = dg;
    await replaceVariables(a, { type: 'chat' });
    const chk = getVariables({ type: 'chat' }) || {};
    chatOk = !!(chk && chk.XZ);
  } catch (e) { console.warn('[XZ] save-chat err:', e); }
  if (!chatOk) {
    try { const a = getVariables() || {}; a.__XZ__ = snap; a.__XZ_digest__ = dg; await replaceVariables(a); } catch (e) { console.warn('[XZ] save-global err:', e); }
  }
}

async function refreshDigest(scan) {
  try {
    const a = getVariables({ type: 'chat' }) || {};
    if (!a.XZ) return;
    a.XZ_digest = digest(root, scan || '');
    await replaceVariables(a, { type: 'chat' });
  } catch (e) { console.warn('[XZ] digest err:', e); }
}

const isSelf = (r, who) => !!(r.p && who && who === r.p.name);

function stub(r, name) {
  return { name, stub: true, fav: 0, job: '', realm: '', org: '', trait: '', look: '', loc: '', note: '', status: '', dead: false, activeAt: Date.now() };
}

function titleCross(r, before, after, table, kind) {
  table.forEach(t => {
    if (before < t[0] && after >= t[0]) {
      if (r.p.titles.indexOf(t[1]) < 0) r.p.titles.push(t[1]);
      r.notes.push('[系统] ' + r.p.name + '的' + kind + '达到' + t[0] + '，获得称号「' + t[1] + '」。请在正文里自然带过。');
    }
  });
}

function calc(v, cur, max) {
  const t = clean(v);
  if (t === '') return null;
  if (t === 'full' || t === '满') return max;
  if (/^[+-]/.test(t)) return clamp(Math.round(cur + num(t, 0)), 0, max);
  const n = Number(t);
  return Number.isFinite(n) ? clamp(Math.round(n), 0, max) : null;
}

const OPS = {
  init(r, a) {
    const p = r.p;
    if (p.inited) return;
    if (clean(a['身份'])) p.ident = clean(a['身份']);
    if (clean(a['灵根']) && p.root === ROOTS[0]) p.root = clean(a['灵根']);
    LIFE.forEach(k => { if (clean(a[k]) !== '') p.life[k] = clamp(Math.round(num(a[k], 10)), 0, 100); });
    BATK.forEach(k => { if (clean(a[k]) !== '') p.bat[k] = clamp(Math.round(num(a[k], 10)), 0, 100); });
    if (clean(a['现金']) !== '') p.cash = Math.max(0, Math.round(num(a['现金'], 0)));
    if (clean(a['灵石']) !== '') p.stone = Math.max(0, Math.round(num(a['灵石'], 0)));
    p.inited = true;
  },
  attr(r, a) {
    const k = clean(a.k);
    const box = LIFE.includes(k) ? r.p.life : BATK.includes(k) ? r.p.bat : null;
    if (!box) return;
    if (clean(a.set) !== '') box[k] = clamp(Math.round(num(a.set, box[k])), 0, 100);
    else box[k] = clamp(Math.round(box[k] + num(a.v, 0)), 0, 100);
  },
  realm(r, a) {
    const p = r.p, v = clean(a.v);
    if (!REALMS.includes(v) || v === p.realm) return;
    const oh = p.hpMax, om = p.mpMax, i = realmIdx(v);
    p.realm = v; p.hpMax = hpOf(i); p.mpMax = mpOf(i);
    p.hp = clamp(p.hp + p.hpMax - oh, 0, p.hpMax);
    p.mp = clamp(p.mp + p.mpMax - om, 0, p.mpMax);
    r.notes.push('[系统] ' + p.name + '的境界变为「' + v + '」。');
  },
  st(r, a) {
    const p = r.p;
    const h = calc(a.hp, p.hp, p.hpMax);
    if (h !== null) {
      p.hp = h;
      if (h === 0) r.notes.push('[系统] ' + p.name + '气血归零。按剧情处理为昏迷或濒死，不要直接写成死亡结局。');
    }
    const m = calc(a.mp, p.mp, p.mpMax);
    if (m !== null) p.mp = m;
  },
  cash(r, a) { r.p.cash = Math.max(0, Math.round(r.p.cash + num(a.v, 0))); },
  stone(r, a) { r.p.stone = Math.max(0, Math.round(r.p.stone + num(a.v, 0))); },
  school(r, a) {
    const name = clean(a.name);
    if (!name) return;
    const list = r.p.schools;
    let o = list.find(x => x.name === name);
    if (!o) {
      if (list.length >= 8) return;
      o = { name, lv: 0, note: '' };
      list.push(o);
      r.notes.push('[系统] ' + r.p.name + '开始接触流派「' + name + '」。');
    }
    const was = gradeOf(o.lv);
    if (clean(a.set) !== '') o.lv = clamp(Math.round(num(a.set, o.lv)), 0, 100);
    else o.lv = clamp(Math.round(o.lv + clamp(num(a.v, 0), -10, 10)), 0, 100);
    if (clean(a.note)) o.note = clean(a.note);
    if (gradeOf(o.lv) !== was && o.lv > 0) r.notes.push('[系统] ' + name + '修习到「' + gradeOf(o.lv) + '」。');
  },
  ally(r, a) {
    const name = clean(a.name);
    if (!name) return;
    const list = r.allies;
    const i = list.findIndex(x => x.name === name);
    if (clean(a.op) === 'del') { if (i >= 0) list.splice(i, 1); return; }
    let o = i >= 0 ? list[i] : null;
    if (!o) {
      if (list.length >= 10) return;
      o = { name, kind: '其他', grade: '', loy: 50, note: '' };
      list.push(o);
    }
    if (ALLY_KINDS.includes(clean(a.kind))) o.kind = clean(a.kind);
    if (clean(a.grade)) o.grade = clean(a.grade);
    if (clean(a.note)) o.note = clean(a.note);
    if (clean(a.loy) !== '') o.loy = /^[+-]/.test(clean(a.loy)) ? clamp(Math.round(o.loy + num(a.loy, 0)), 0, 100) : clamp(Math.round(num(a.loy, o.loy)), 0, 100);
  },
  item(r, a) {
    const op = clean(a.op) || 'get';
    const name = clean(a.name);
    if (!name) return;
    const n = Math.max(1, Math.round(num(a.n, 1)));
    const bag = r.p.bag;
    const it = bag.find(x => x.name === name);
    if (op === 'get') {
      if (it) { it.n += n; if (clean(a.eff)) it.eff = clean(a.eff); }
      else bag.push({ name, n, rank: RANKS.includes(clean(a.rank)) ? clean(a.rank) : '凡品', type: ITEM_TYPES.includes(clean(a.type)) ? clean(a.type) : guessType(name), eff: clean(a.eff) });
    } else if ((op === 'use' || op === 'lose') && it) {
      it.n -= n;
      if (it.n <= 0) bag.splice(bag.indexOf(it), 1);
    }
  },
  buff(r, a) {
    const name = clean(a.name);
    if (!name) return;
    const list = r.p.buffs;
    const i = list.findIndex(x => x.name === name);
    if (clean(a.op) === 'del') { if (i >= 0) list.splice(i, 1); return; }
    const days = Math.round(num(a.days, 0));
    const o = { name, eff: clean(a.eff) || (i >= 0 ? list[i].eff : ''), until: days > 0 ? r.day + days : 0 };
    if (i >= 0) list[i] = o; else list.push(o);
    if (list.length > 12) list.splice(0, list.length - 12);
  },
  city(r, a) {
    const name = clean(a.name);
    if (!name) return;
    const o = r.cities[name] || (r.cities[name] = { name, region: '', desc: '', visited: false, firstDay: r.day });
    if (clean(a.region)) o.region = clean(a.region);
    if (clean(a.desc)) o.desc = clean(a.desc);
  },
  go(r, a) {
    const city = clean(a.city);
    if (!city) return;
    if (!r.cities[city]) OPS.city(r, { name: city });
    r.cities[city].visited = true;
    r.p.city = city;
    r.p.spot = clean(a.spot);
  },
  org(r, a) {
    const name = clean(a.name);
    if (!name) return;
    let o = r.orgs[name];
    if (!o) o = r.orgs[name] = { name, city: '', kind: '其他', desc: '', rep: 0 };
    if (clean(a.city)) { o.city = clean(a.city); if (!r.cities[o.city]) OPS.city(r, { name: o.city }); }
    if (ORG_KINDS.includes(clean(a.kind))) o.kind = clean(a.kind);
    if (clean(a.desc)) o.desc = clean(a.desc);
    if (clean(a.rep) !== '') {
      const was = stanceOf(o.rep);
      o.rep = clamp(Math.round(o.rep + num(a.rep, 0)), -100, 100);
      if (stanceOf(o.rep) !== was) r.notes.push('[系统] ' + name + '对' + r.p.name + '的态度变为「' + stanceOf(o.rep) + '」。');
    }
  },
  npc(r, a) {
    const name = clean(a.name);
    if (!name || isSelf(r, name)) return;
    const o = r.npcs[name] || (r.npcs[name] = stub(r, name));
    ['job', 'realm', 'org', 'trait', 'look', 'loc', 'note', 'status'].forEach(k => { const v = clean(a[k]); if (v) o[k] = v; });
    if (/^(无|正常|没有)$/.test(o.status || '')) o.status = '';
    o.stub = false;
    if (clean(a.dead) === '1') { o.dead = true; r.notes.push('[系统] ' + name + '已死亡。'); }
    o.activeAt = Date.now();
  },
  fav(r, a) {
    const name = clean(a.name);
    if (!name || isSelf(r, name)) return;
    if (!r.npcs[name]) r.npcs[name] = stub(r, name);
    const o = r.npcs[name];
    const was = o.fav;
    o.fav = clamp(Math.round(was + num(a.v, 0)), -100, 100);
    [50, 80].forEach(th => { if (was < th && o.fav >= th) r.notes.push('[系统] ' + name + '的好感达到' + th + '。'); });
    if (was > -50 && o.fav <= -50) r.notes.push('[系统] ' + name + '的好感跌至-50，已视为敌意。');
    o.activeAt = Date.now();
  },
  fame(r, a) {
    const m0 = r.fame.merit, k0 = r.fame.karma;
    r.fame.merit = Math.max(0, Math.round(m0 + num(a.merit, 0)));
    r.fame.karma = Math.max(0, Math.round(k0 + num(a.karma, 0)));
    titleCross(r, m0, r.fame.merit, MERIT_T, '功德');
    titleCross(r, k0, r.fame.karma, KARMA_T, '业力');
  },
  aura(r, a) {
    const was = r.aura;
    r.aura = clamp(Math.round(was + clamp(num(a.v, 0), -20, 20)), 0, 100);
    const oldTier = AURA_T.findIndex(x => was < x[0]);
    const newTier = AURA_T.findIndex(x => r.aura < x[0]);
    if (oldTier !== newTier) {
    r.notes.push('[系统·世界] 天地灵气浓度进入新的档位：' + auraText(r.aura));
}
  },
  clue(r, a) {
    const id = normClue(a.id);
    const s = clueStage(id);
    if (!id || s !== r.stage || !PLOT[s - 1].clues[id] || r.clues.indexOf(id) >= 0) return;
    r.clues.push(id);
    const P = PLOT[r.stage - 1];
    const got = r.clues.filter(x => clueStage(x) === r.stage).length;
    if (r.stage < 5 && got >= P.need) {
      r.stage++;
      r.notes.push('[系统·幕后] 阴谋推进至阶段' + r.stage + '「' + PLOT[r.stage - 1].name + '」。之后的局势逐步体现新阶段，不要一次性揭露。');
    }
  },
  day(r, a) {
    const add = clamp(Math.round(num(a.add, 0)), 0, DAY_STEP_MAX);
    if (!add) return;
    const oldDay = r.day;
    r.day += add;
    const drift = Math.floor(r.day / 30) - Math.floor(oldDay / 30);
    if (drift > 0) OPS.aura(r, { v: drift });
    r.p.buffs = r.p.buffs.filter(x => !x.until || r.day < x.until);
  }
};

const ORDER = ['init', 'realm', 'attr', 'city', 'go', 'org', 'npc', 'fav', 'st', 'cash', 'stone', 'school', 'ally', 'item', 'buff', 'fame', 'aura', 'clue', 'day'];

function apply(r, a) {
  const t = clean(a.t);
  if (!OPS[t]) return;
  try { OPS[t](r, a); } catch (e) { console.warn('[XZ] op err:', t, e); }
}

function npcLine(o) {
  if (o.stub) return '【' + o.name + '】档案未完善，请在其下次登场时输出 npc 建档。好感' + fmtS(o.fav) + '。';
  return '【' + o.name + '】' + [o.job, o.realm, o.org ? '隶属' + o.org : ''].filter(Boolean).join('·') + '　好感' + fmtS(o.fav) +
    (o.loc ? '　所在：' + o.loc : '') + (o.look ? '　外貌：' + o.look : '') + (o.trait ? '　性格：' + o.trait : '') + (o.note ? '　备注：' + o.note : '') +
    (o.status ? '　状态：' + o.status : '') + (o.dead ? '　已死亡' : '');
}

function digest(r, scan) {
  norm(r);
  if (!r.made || !r.p) return '【系统】玩家尚未建档。正常推进剧情，不要输出任何 upd 标签，结尾用一句括号内的系统提示提醒玩家点击「面板」建档。';
  const p = r.p, L = [];
  L.push('【' + p.name + '】' + (p.ident ? p.ident + '　' : '') + '灵根：' + p.root + '　境界：' + p.realm + '　气血 ' + p.hp + '/' + p.hpMax + '　灵力 ' + p.mp + '/' + p.mpMax +
    '　现金¥' + p.cash + '　灵石' + p.stone + '　功德' + r.fame.merit + '　业力' + r.fame.karma + '　称号：' + (p.title || '无'));
  if (!p.inited) L.push('【待办】' + p.name + '尚未初始化数值。本轮回复末尾必须输出一条 <upd t="init" 身份="" 灵根="" 学识="" 口才="" 魅力="" 人脉="" 胆识="" 手艺="" 力量="" 敏捷="" 体质="" 神识="" 现金="">，数值依据' + p.name + '的人设与身份：普通人生活属性约10到40，战斗属性约5到15，有特殊背景可以偏离，现金为人民币。灵根仍是未觉醒时不要写灵根。');
  L.push('【所在】' + (p.city || '未知') + (p.spot ? '·' + p.spot : '') + '　第' + r.day + '日。剧情跨入次日或经过数日时，必须输出 <upd t="day" add="天数">。');
  L.push('【生活属性】' + LIFE.map(k => k + p.life[k]).join('　') + '　（满值100，普通成年人约10到40）');
  L.push('【战斗属性】' + BATK.map(k => k + p.bat[k]).join('　') + '　（满值100，普通人约5到15）');
  L.push('【流派】' + (p.schools.length ? p.schools.map(s => s.name + '·' + gradeOf(s.lv) + s.lv + (s.note ? '（' + s.note + '）' : '')).join('　') : '无') + '。流派之外的术法只能是粗浅的皮毛。');
  if (r.allies.length) L.push('【随从】' + r.allies.map(x => x.name + '（' + x.kind + (x.grade ? '·' + x.grade : '') + '·忠诚' + x.loy + (x.note ? '·' + x.note : '') + '）').join('　'));
  L.push('【状态效果】' + (p.buffs.length ? p.buffs.map(b => b.name + (b.eff ? '（' + b.eff + '）' : '') + (b.until ? '至第' + b.until + '日' : '')).join('、') : '无'));
  L.push('【背包】' + (p.bag.length ? p.bag.slice(0, 40).map(x => x.name + '×' + x.n + '（' + x.rank + (x.eff ? '·' + x.eff : '') + '）').join('、') : '空'));
  L.push('【灵气浓度】' + r.aura + '/100　' + auraText(r.aura) + '。描写环境、术法威力与修炼速度时以此为准，浓度变化由剧情事件推动，输出 <upd t="aura" v="">。');
  L.push('【功德与业力】功德是行善积累的可消耗资源，可兑换机缘或抵消劫数。但它不是通用货币。只有明确发生消耗功德的仪式、抵灾、兑换或特殊因果行为时，才允许减少功德。普通买卖、修炼和使用法器不得消耗功德，消耗时输出负数的 fame merit。业力来自邪术、杀戮与害人，业力高时鬼物纠缠、天劫加重、正道人士避之不及。功德高时运势顺遂、鬼物退避、容易得到善缘。正当防卫、战斗中的必要伤害和意外死亡不自动等同于业力；主动虐杀、滥杀、夺舍、血祭和以他人为材料才会显著增加业力。');
  const here = r.cities[p.city];
  if (here) {
    const ho = Object.keys(r.orgs).filter(n => r.orgs[n].city === here.name);
    L.push('【当前城市】' + here.name + (here.region ? '（' + here.region + '）' : '') + (here.desc ? '：' + here.desc : '') + (ho.length ? '　本城势力：' + ho.map(n => n + '·' + stanceOf(r.orgs[n].rep) + (r.orgs[n].desc ? '（' + r.orgs[n].desc + '）' : '')).join('、') : '　本城势力尚未登录'));
  }
  const ck = Object.keys(r.cities);
  L.push('【已登录城市】' + (ck.length ? ck.slice(-30).join('、') : '无') + '。新城市首次出现需输出 city 建档，同时为其登场的势力输出 org 建档。');
  const ok = Object.keys(r.orgs);
  if (ok.length) L.push('【势力名册】' + ok.slice(-40).map(n => n + '（' + r.orgs[n].kind + (r.orgs[n].city ? '·' + r.orgs[n].city : '') + '·' + stanceOf(r.orgs[n].rep) + '）').join('、'));
  const P = PLOT[r.stage - 1];
  L.push('【幕后控制·不得直接告知玩家】主线阶段' + r.stage + '「' + P.name + '」：' + P.control + '主线只是背景。玩家不理会时世界照常运转，局势按各势力的动向缓慢发展，不得强行把玩家拖入主线，也不得因此惩罚玩家。玩家主动追查或路过相关地点时，才通过传闻、物件、人物行为埋下线索。');
  const left = Object.keys(P.clues).filter(id => r.clues.indexOf(id) < 0);
  if (left.length) L.push('【幕后线索控制】本阶段尚未发现的线索编号：' + left.join('、') + '。只有玩家实际通过探索、调查、交易或冲突获得线索时，才输出对应 clue；不得直接展示线索文本。');
  const names = Object.keys(r.npcs);
  const pick = [];
  const add = n => { if (n && r.npcs[n] && pick.indexOf(n) < 0) pick.push(n); };
  const txt = String(scan || '');
  names.forEach(n => { if (txt.indexOf(n) >= 0) add(n); });
  names.slice().sort((a, b) => (r.npcs[b].activeAt || 0) - (r.npcs[a].activeAt || 0)).slice(0, 4).forEach(add);
  names.forEach(n => { if (!r.npcs[n].dead && r.npcs[n].loc && r.npcs[n].loc === p.city) add(n); });
  if (pick.length) {
    L.push('【人物档案】以下为既有档案，身份、境界、好感以此为准，不得重新设定，不得重复建档：');
    pick.slice(0, 8).forEach(n => L.push(npcLine(r.npcs[n])));
  }
  const rest = names.filter(n => pick.slice(0, 8).indexOf(n) < 0).sort((a, b) => (r.npcs[b].activeAt || 0) - (r.npcs[a].activeAt || 0)).slice(0, 40);
  if (rest.length) L.push('【名册·已建档】' + rest.map(n => { const o = r.npcs[n]; return n + '（' + (o.stub ? '待建档' : o.job || '已建档') + (o.dead ? '·已死亡' : '') + '）'; }).join('、'));
  if (r.notes.length) L.push('【系统通知】' + r.notes.join(' '));
  return L.join('\n');
}

function parseUpd(t) {
  let s = String(t || '');
  s = s.replace(/```[\s\S]*?```/g, '');
  const out = [];
  const re = /<upd\s+((?:"[^"]*"|“[^”]*”|'[^']*'|[^">])*)\/?>/gi;
  let m;
  while ((m = re.exec(s))) {
    const a = {};
    const ar = /([\w\u4e00-\u9fa5.]+)\s*=\s*(?:"([^"]*)"|“([^”]*)”|'([^']*)')/g;
    let x;
    while ((x = ar.exec(m[1]))) {
      const val = x[2] !== undefined ? x[2] : (x[3] !== undefined ? x[3] : x[4]);
      a[x[1]] = String(val == null ? '' : val).replace(/｜/g, '|');
    }
    if (Object.keys(a).length) out.push(a);
  }
  return out;
}

function stateSnapshot(r) {
  const o = {};
  Object.keys(r).forEach(k => { if (k !== 'processed') o[k] = r[k]; });
  return JSON.parse(JSON.stringify(o));
}

function restoreSnapshot(r, s) {
  Object.keys(s).forEach(k => { if (k !== 'processed') r[k] = JSON.parse(JSON.stringify(s[k])); });
}

function textSig(t) {
  let h = 2166136261;
  const s = String(t || '');
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(36);
}

async function settleMessage(id) {
  const ms = await getChatMessages(id, { include_swipes: true });
  if (!ms || !ms.length) return;
  const msg = ms[0];
  if (msg.role !== 'assistant') return;
  const msgKey = String(msg.message_id ?? id);
  const swipeId = Number(msg.swipe_id ?? 0);
  const message = Array.isArray(msg.swipes) ? String(msg.swipes[swipeId] ?? '') : String(msg.message ?? '');
  const sig = textSig(message);
  load();
  root.processed = root.processed || {};
  const maxKey = Object.keys(root.processed).reduce((n, k) => Math.max(n, Number(k) || 0), -1);
  const old = root.processed[msgKey];
  if (old && typeof old === 'object' && old.swipeId === swipeId && old.sig === sig) return;
  const hasLater = () => Object.entries(root.processed).some(([k, v]) => k !== msgKey && v && typeof v === 'object' && Number(v.at || 0) > Number((old && old.at) || 0));
  if (!old && Number(msgKey) < maxKey) {
    root.processed[msgKey] = { swipeId, sig, at: 0 };
    await save(message);
    return;
  }
  if (old && typeof old === 'object' && old.before && !hasLater()) {
    const keep = root.processed;
    restoreSnapshot(root, old.before);
    root.processed = keep;
    delete root.processed[msgKey];
  } else if (old) {
    root.processed[msgKey] = { swipeId, sig, at: Number(old.at) || 0 };
    await save(message);
    return;
  }
  const before = stateSnapshot(root);
root.notes = [];
if (root.made && root.p) {
  const list = parseUpd(message);
  let clueUsed = false;
  list.sort((a, b) => ORDER.indexOf(clean(a.t)) - ORDER.indexOf(clean(b.t))).forEach(a => {
    if (clean(a.t) === 'clue') {
      if (clueUsed) return;
      clueUsed = true;
    }
    apply(root, a);
  });
  const now = Date.now();
    Object.keys(root.npcs).forEach(n => { if (message.indexOf(n) >= 0) root.npcs[n].activeAt = now; });
  }
  root.processed[msgKey] = { swipeId, sig, before, at: Date.now() };
  const keys = Object.keys(root.processed).sort((a, b) => Number(a) - Number(b));
  keys.slice(0, Math.max(0, keys.length - 3)).forEach(k => { const o = root.processed[k]; if (o && o.before) delete o.before; });
  if (keys.length > 400) keys.slice(0, keys.length - 400).forEach(k => delete root.processed[k]);
  await save(message);
  if (ov && ov.style.display !== 'none') draw();
}

let settleQueue = Promise.resolve();
function queueSettlement(id) {
  settleQueue = settleQueue.then(() => settleMessage(id)).catch(e => console.warn('[XZ]', e));
}

async function onUserSent(id) {
  try {
    const ms = await getChatMessages(id);
    if (!ms || !ms.length) return;
    load();
    if (!root.made) return;
    let prev = '';
    try { const pm = await getChatMessages(Number(id) - 1); prev = String((pm && pm[0] && pm[0].message) || ''); } catch (e) { }
    await refreshDigest(String(ms[0].message || '') + '\n' + prev);
  } catch (e) { console.warn('[XZ] sent err:', e); }
}

eventOn(tavern_events.MESSAGE_RECEIVED, queueSettlement);
eventOn(tavern_events.MESSAGE_UPDATED, queueSettlement);
try { eventOn(tavern_events.MESSAGE_SWIPED, queueSettlement); } catch (e) { }
try { eventOn(tavern_events.MESSAGE_SENT, id => { settleQueue = settleQueue.then(() => onUserSent(id)); }); } catch (e) { }
try {
  eventOn(tavern_events.MESSAGE_DELETED, n => {
    settleQueue = settleQueue.then(async () => {
      load();
      root.processed = root.processed || {};
      const cut = Number(n);
      if (!Number.isFinite(cut)) return;
      const killed = Object.keys(root.processed).filter(k => Number(k) >= cut).sort((a, b) => Number(a) - Number(b));
      if (!killed.length) return;
      let base = null;
      for (let i = 0; i < killed.length; i++) { const o = root.processed[killed[i]]; if (o && typeof o === 'object' && o.before) { base = o.before; break; } }
      if (base) restoreSnapshot(root, base);
      killed.forEach(k => delete root.processed[k]);
      await save();
      if (ov && ov.style.display !== 'none') draw();
    }).catch(e => console.warn('[XZ]', e));
  });
} catch (e) { }
try {
  eventOn(tavern_events.CHAT_CHANGED, () => {
    close();
    settleQueue = Promise.resolve();
    cf = null; openNpc = '';
    load();
  });
} catch (e) { }

function ask(text) {
  try { return W.confirm(text); } catch (e) { return confirm(text); }
}

