`;

let ov = null, page = 'char', cf = null, openNpc = '';

function build() {
  if (ov && D.body.contains(ov)) return;
  let st = D.getElementById('xz-css');
  if (!st) { st = D.createElement('style'); st.id = 'xz-css'; D.head.appendChild(st); }
  st.textContent = CSS;
  ov = D.createElement('div');
  ov.id = 'xz-ov';
  ov.innerHTML = '<div class="x-mask"></div><div class="x-win" role="dialog">' +
    '<div class="x-hd"><div class="x-t">修真面板</div><div class="x-s" id="xzSub"></div><div class="x-x" title="关闭">×</div></div>' +
    '<div class="x-tabs" id="xzTabs"></div><div class="x-body" id="xzBody"></div></div>';
  D.body.appendChild(ov);
  ov.querySelector('.x-mask').addEventListener('click', close);
  ov.querySelector('.x-x').addEventListener('click', close);
}

function open() { build(); load(); ov.style.display = 'block'; draw(); }
function close() { if (ov) ov.style.display = 'none'; }

const PAGES = [['char', '角色'], ['bag', '背包'], ['ally', '随从'], ['npc', '人物'], ['org', '势力'], ['fame', '声望']];

function draw() {
  load();
  const sub = ov.querySelector('#xzSub');
  const tabs = ov.querySelector('#xzTabs');
  const b = ov.querySelector('#xzBody');
  b.scrollTop = 0;
  if (!root.made || !root.p) {
    sub.textContent = '建档';
    tabs.innerHTML = '';
    pgCreate(b);
    return;
  }
  sub.textContent = root.p.name + '　' + root.p.realm + '　' + (root.p.city || '未知') + '　第' + root.day + '日';
  tabs.innerHTML = PAGES.map(p => '<div class="x-tab' + (p[0] === page ? ' on' : '') + '" data-p="' + p[0] + '" tabindex="0">' + p[1] + '</div>').join('');
  tabs.querySelectorAll('.x-tab').forEach(t => t.onclick = () => { page = t.dataset.p; draw(); });
  ({ char: pgChar, bag: pgBag, ally: pgAlly, npc: pgNpc, org: pgOrg, fame: pgFame })[page](b);
}

function bar(cls, cur, max, label, right) {
  return '<div class="blab"><span>' + label + '</span><span>' + (right === undefined ? cur + ' / ' + max : right) + '</span></div>' +
    '<div class="bar ' + cls + '"><i style="width:' + pct(cur, max) + '%"></i></div>';
}

function optList(arr, sel) {
  return arr.map(x => '<option value="' + H(x) + '"' + (x === sel ? ' selected' : '') + '>' + H(x) + '</option>').join('');
}

function pgCreate(el) {
  if (!cf) {
    let nm = '';
    try { nm = substitudeMacros('{{user}}'); } catch (e) { }
    cf = { name: nm || '', ident: '', root: ROOTS[0], schools: [] };
  }
  let h = '<div class="sec">身份</div>' +
    '<div class="fld"><label>名字</label><input data-f="name" value="' + H(cf.name) + '" placeholder="与你的用户名一致"></div>' +
    '<div class="fld"><label>身份（一句话，可留空）</label><input data-f="ident" value="' + H(cf.ident) + '" placeholder="留空则由AI按你的人设判定，如：大三学生、外卖员、小公司会计"></div>' +
    '<div class="fld"><label>灵根</label><select data-f="root">' + optList(ROOTS, cf.root) + '</select>' +
    '<div class="hint">选「未觉醒」则由剧情决定，适合普通人开局。</div></div>' +
    '<div class="sec">起始流派（最多2个，可不选）</div><div class="btns" style="margin-top:0">' +
    SCHOOLS.map(s => '<span class="btn' + (cf.schools.includes(s.k) ? ' on' : '') + '" data-sc="' + s.k + '">' + s.k + '</span>').join('') + '</div>' +
    '<div class="hint" style="color:#a89f8c">' + (cf.schools.length ? cf.schools.map(k => k + '：' + SCHOOLS.find(s => s.k === k).d).join('；') : '点选查看说明。其他流派之后可在剧情中拜师或自学。') + '</div>' +
    '<div class="hint" id="xzErr"></div><div class="btn big" id="xzGo">建档</div>';
  el.innerHTML = h;
  el.querySelectorAll('[data-f]').forEach(i => {
    const f = () => { cf[i.dataset.f] = i.value; };
    i.addEventListener('input', f);
    i.addEventListener('change', f);
  });
  el.querySelectorAll('[data-sc]').forEach(x => x.onclick = () => {
    const k = x.dataset.sc, i = cf.schools.indexOf(k);
    if (i >= 0) cf.schools.splice(i, 1);
    else if (cf.schools.length < 2) cf.schools.push(k);
    draw();
  });
  el.querySelector('#xzGo').onclick = createGame;
}

async function createGame() {
  const err = ov.querySelector('#xzErr');
  const name = clean(cf.name);
  if (!name) { err.textContent = '请填写名字。'; return; }
  const r = blank();
  r.made = true;
  const life = {}, bat = {};
  LIFE.forEach(k => { life[k] = 10; });
  BATK.forEach(k => { bat[k] = 10; });
  r.p = {
    name, ident: clean(cf.ident), root: cf.root, realm: '凡人', city: '', spot: '', inited: false,
    hp: hpOf(0), hpMax: hpOf(0), mp: mpOf(0), mpMax: mpOf(0), life, bat, cash: 1000, stone: 0,
    schools: cf.schools.map(k => ({ name: k, lv: 5, note: '' })), bag: [], buffs: [], title: '', titles: []
  };
  root = r;
  root.processed = {};
  await save();
  cf = null; page = 'char';
  draw();
}

function pgChar(el) {
  const p = root.p;
  let h = '<div class="card hot"><div class="ch"><span class="cn" style="font-size:16px">' + H(p.name) + '</span><span class="gold">' + H(p.realm) + '</span></div>' +
    '<div style="margin-top:5px"><span class="x-tag">' + H(p.root) + '</span>' + (p.ident ? '<span class="x-tag">' + H(p.ident) + '</span>' : '') +
    (p.title ? '<span class="x-tag gold">' + H(p.title) + '</span>' : '') + '</div>' +
    bar('b-hp', p.hp, p.hpMax, '气血') + bar('b-mp', p.mp, p.mpMax, '灵力') + '</div>' +
    '<div class="sec">钱财</div><div class="row"><span class="k">现金</span><span class="v gold">¥ ' + p.cash + '</span></div>' +
    '<div class="row"><span class="k">灵石</span><span class="v gold">' + p.stone + '</span></div>' +
    '<div class="sec">生活属性</div><div class="grid">' + LIFE.map(k => '<div>' + bar('b-le', p.life[k], 100, k) + '</div>').join('') + '</div>' +
    '<div class="sec">战斗属性</div><div class="grid">' + BATK.map(k => '<div>' + bar('b-at', p.bat[k], 100, k) + '</div>').join('') + '</div>' +
    '<div class="sec">流派</div>';
  if (!p.schools.length) h += '<div class="empty">尚未入门任何流派。</div>';
  p.schools.forEach(s => {
    h += '<div class="card"><div class="ch" style="cursor:default"><span class="cn">' + H(s.name) + '</span><span class="gold">' + gradeOf(s.lv) + '</span></div>' +
      bar('b-at', s.lv, 100, '熟练度') + (s.note ? '<div class="cd">' + H(s.note) + '</div>' : '') + '</div>';
  });
  h += '<div class="sec">状态效果</div>';
  if (!p.buffs.length) h += '<div class="empty">当前没有状态效果。</div>';
  p.buffs.forEach(b => {
    h += '<div class="row"><span class="k">' + H(b.name) + '</span><span class="v">' + H(b.eff || '') + (b.until ? '<span class="dim">　至第' + b.until + '日</span>' : '') + '</span></div>';
  });
  h += '<div class="sec">存档</div><div class="btn warn" id="xzReset">重置本局存档</div>';
  el.innerHTML = h;
  el.querySelector('#xzReset').onclick = async () => {
    if (!ask('确定要清空本聊天的全部系统数据并重新建档吗？此操作无法撤销。')) return;
    root = blank(); cf = null; page = 'char';
    await save();
    draw();
  };
}

function pgBag(el) {
  const p = root.p;
  let h = '';
  if (!p.bag.length) h = '<div class="empty">背包是空的。</div>';
  ITEM_TYPES.forEach(t => {
    const list = p.bag.filter(x => x.type === t);
    if (!list.length) return;
    h += '<div class="sec">' + t + '</div>';
    list.forEach(x => {
      h += '<div class="card"><div class="ch" style="cursor:default"><span class="cn" style="color:' + (RANK_COLOR[x.rank] || '#ece5d8') + '">' + H(x.name) + '</span><span class="gold">×' + x.n + '</span></div>' +
        '<div class="cd dim">' + H(x.rank) + '</div>' + (x.eff ? '<div class="cd">' + H(x.eff) + '</div>' : '') + '</div>';
    });
  });
  el.innerHTML = h;
}

function pgAlly(el) {
  let h = '<div class="sec">随从</div>';
  if (!root.allies.length) h += '<div class="empty">身边还没有鬼仆、仙家或灵宠。</div>';
  root.allies.forEach(x => {
    h += '<div class="card"><div class="ch" style="cursor:default"><span class="cn">' + H(x.name) + '</span><span class="x-tag">' + H(x.kind) + (x.grade ? '·' + H(x.grade) : '') + '</span></div>' +
      bar('b-me', x.loy, 100, '忠诚') + (x.note ? '<div class="cd">' + H(x.note) + '</div>' : '') + '</div>';
  });
  el.innerHTML = h;
}

function pgNpc(el) {
  const names = Object.keys(root.npcs).sort((a, b) => (root.npcs[b].activeAt || 0) - (root.npcs[a].activeAt || 0));
  let h = '<div class="sec">人物（' + names.length + '）</div>';
  if (!names.length) h += '<div class="empty">尚未结识任何人。</div>';
  names.forEach(n => {
    const o = root.npcs[n], open = openNpc === n;
    h += '<div class="card' + (o.dead ? ' dead' : '') + '"><div class="ch" data-n="' + H(n) + '"><span class="cn">' + H(n) + '</span><span class="dim">' + H(o.stub ? '待建档' : [o.job, o.realm].filter(Boolean).join('·')) + '</span></div>' +
      bar('b-me', o.fav + 100, 200, '好感', fmtS(o.fav));
    if (open && !o.stub) {
      h += (o.org ? '<div class="cd">隶属：' + H(o.org) + '</div>' : '') + (o.loc ? '<div class="cd">所在：' + H(o.loc) + '</div>' : '') +
        (o.look ? '<div class="cd">外貌：' + H(o.look) + '</div>' : '') + (o.trait ? '<div class="cd">性格：' + H(o.trait) + '</div>' : '') +
        (o.note ? '<div class="cd">备注：' + H(o.note) + '</div>' : '') + (o.status ? '<div class="cd">状态：' + H(o.status) + '</div>' : '');
    }
    h += '</div>';
  });
  el.innerHTML = h;
  el.querySelectorAll('[data-n]').forEach(x => x.onclick = () => { openNpc = openNpc === x.dataset.n ? '' : x.dataset.n; draw(); });
}

function orgCard(o) {
  return '<div class="card"><div class="ch" style="cursor:default"><span class="cn">' + H(o.name) + '</span><span><span class="x-tag">' + H(o.kind) + '</span><span class="x-tag gold">' + stanceOf(o.rep) + '</span></span></div>' +
    bar('b-me', o.rep + 100, 200, '声望', fmtS(o.rep)) + (o.desc ? '<div class="cd">' + H(o.desc) + '</div>' : '') + '</div>';
}

function pgOrg(el) {
  const p = root.p;
  const cities = Object.keys(root.cities).sort((a, b) => (a === p.city ? -1 : b === p.city ? 1 : 0));
  let h = '';
  if (!cities.length && !Object.keys(root.orgs).length) h = '<div class="empty">尚未登录任何城市与势力。</div>';
  cities.forEach(n => {
    const c = root.cities[n];
    h += '<div class="sec">' + H(n) + (c.visited ? '' : '（听闻）') + '</div>' +
      (c.region || c.desc ? '<div class="cd dim" style="margin:0 0 8px">' + H([c.region, c.desc].filter(Boolean).join('　')) + '</div>' : '');
    const list = Object.keys(root.orgs).filter(k => root.orgs[k].city === n);
    if (!list.length) h += '<div class="empty">本城势力尚未登录。</div>';
    list.forEach(k => { h += orgCard(root.orgs[k]); });
  });
  const free = Object.keys(root.orgs).filter(k => !root.orgs[k].city || !root.cities[root.orgs[k].city]);
  if (free.length) {
    h += '<div class="sec">无定所</div>';
    free.forEach(k => { h += orgCard(root.orgs[k]); });
  }
  el.innerHTML = h;
}

const nextT = (v, table) => { const t = table.find(x => v < x[0]); return t ? t[0] : table[table.length - 1][0]; };

function pgFame(el) {
  const f = root.fame, p = root.p;
  let h = '<div class="sec">功德与业力</div>' +
    bar('b-me', f.merit, nextT(f.merit, MERIT_T), '功德') +
    bar('b-ka', f.karma, nextT(f.karma, KARMA_T), '业力') +
    '<div class="sec">天地灵气</div>' + bar('b-au', root.aura, 100, '灵气浓度') +
    '<div class="cd">' + H(auraText(root.aura)) + '</div>' +
    '<div class="sec">称号</div>';
  if (!p.titles.length) h += '<div class="empty">尚未获得称号。</div>';
  else h += '<div class="btns">' + p.titles.map(t => '<span class="btn' + (p.title === t ? ' on' : '') + '" data-title="' + H(t) + '">' + H(t) + '</span>').join('') +
    '<span class="btn' + (p.title ? '' : ' off') + '" data-title="">不佩戴</span></div>';
  h += '<div class="sec">已知线索</div>';
  if (!root.clues.length) h += '<div class="empty">尚未发现线索。</div>';
  root.clues.forEach(id => { h += '<div class="card"><div class="cd" style="margin-top:0">' + H(clueText(id)) + '</div></div>'; });
  el.innerHTML = h;
  el.querySelectorAll('[data-title]').forEach(x => x.onclick = async () => { root.p.title = x.dataset.title; await save(); draw(); });
}

