      return p;
    };
    const addLikes = (p, arr) => arr.forEach(n => { n = norm(n); if (n && p.likeList.indexOf(n) < 0) p.likeList.push(n); });
    const addCm = (p, name, text, to) => {
      name = norm(name || '');
      if (!name || !text) return;
      if (!p.commentList.some(c => c.name === name && c.text === text)) p.commentList.push({ name, text, to: to ? norm(to) : '' });
    };
    for (const m of msgs) {
      const t = m.message || '';
      if (m.role === 'user') {
        if (t.indexOf('【朋友圈】') !== 0) continue;
        let mt = t.match(/^【朋友圈】[^：:\n]*?发布动态[：:]([\s\S]*)$/);
        if (mt) {
          const im = mt[1].match(/^([\s\S]*?)(?:【图片[：:]([\s\S]*?)】)?\s*$/);
          put('我', (im[1] || '').trim(), (im[2] || '').trim(), '刚刚');
          continue;
        }
        mt = t.match(/^【朋友圈】[^：:\n]*?评论([^：:\n]+?)的动态[：:]([\s\S]*)$/);
        if (mt) {
          const p = newest(norm(mt[1].trim()));
          if (p) addCm(p, '我', mt[2].trim(), '');
        }
        continue;
      }
      if (m.role !== 'assistant') continue;
      const re = /<PYQ>([\s\S]*?)<\/PYQ>/g;
      let mm;
      while ((mm = re.exec(t)) !== null) {
        let cur;
        mm[1].split('\n').forEach(line => {
          line = line.trim();
          if (!line) return;
          const p = line.split(/[|｜]/).map(s => s.trim());
          if (p[0] === '发布') {
            const author = norm(p[1] || '');
            if (author && (p[2] || p[3])) cur = put(author, p[2] || '', p[3] || '', p[4] || '');
          } else if (p[0] === '帖') {
            cur = newest(norm(p[1] || ''));
          } else if (p[0] === '赞') {
            const target = cur === undefined ? newest('我') : cur;
            if (target) addLikes(target, p.slice(1));
          } else if (p[0] === '评论') {
            const target = cur === undefined ? newest('我') : cur;
            if (target) addCm(target, p[1], p[2], p[3]);
          }
        });
      }
    }
    return dyn.reverse().concat(defs);
  }

  function parseAttrs(s) {
    const out = {};
    const re = /([A-Za-z_][\w-]*)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
    let m;
    while ((m = re.exec(String(s || '')))) {
      out[m[1]] = m[2] !== undefined ? m[2] : m[3];
    }
    return out;
  }

  function parseMarket(msgs) {
    const map = {};
    const talk = {};
    const say = (id, from, text) => {
      if (!id || !text) return;
      (talk[id] = talk[id] || []).push({ from, text });
    };
    for (const m of msgs) {
      const text = String(m.message || '');
      if (m.role === 'user') {
        const mt = text.match(/^【黑市询价】商品id：([^；\n]+)；[\s\S]*?玩家询问：([\s\S]*?)(?:【要求】[\s\S]*)?$/);
        if (mt) say(mt[1].trim(), '我', mt[2].trim());
        continue;
      }
      if (m.role !== 'assistant') continue;

      const re = /<market\b([^>]*)\/?>/gi;
      let hit;
      while ((hit = re.exec(text))) {
        const a = parseAttrs(hit[1]);
        if (!a.id || !a.name) continue;
        map[a.id] = {
          id: a.id,
          seller: a.seller || '匿名卖家',
          name: a.name,
          type: a.type || '杂物',
          rank: a.rank || '凡品',
          price: Math.max(0, Number(a.price) || 0),
          stock: Math.max(0, Number(a.stock) || 1),
          eff: a.eff || '',
          desc: a.desc || ''
        };
      }

      const replyRe = /<market_reply\b((?:[^>"']|"[^"]*"|'[^']*')*?)\/?>/gi;
      while ((hit = replyRe.exec(text))) {
        const a = parseAttrs(hit[1]);
        say(a.id, a.seller || '卖家', a.text);
      }

      const resultRe = /<market_result\b([^>]*)\/?>/gi;
      while ((hit = resultRe.exec(text))) {
        const a = parseAttrs(hit[1]);
        if (a.id && a.ok === '0' && map[a.id]) {
          map[a.id].stock = 0;
          map[a.id].soldOut = true;
          map[a.id].result = a.reason || '商品已无法交易。';
        }
      }
    }
    return Object.values(map).filter(x => x.stock > 0 || x.soldOut).map(x => {
      x.talk = talk[x.id] || [];
      return x;
    });
  }

  function parseForum(msgs) {
    const posts = [];
    const findPost = (title, pid) => {
      if (pid) { const hit = posts.find(x => x.pid === pid); if (hit) return hit; }
      for (let i = posts.length - 1; i >= 0; i--) if (posts[i].title === title) return posts[i];
      return null;
    };
    const addPost = (author, title, content, time, mine, board, pid) => {
      if (!author || !title || !content) return;
      if (posts.some(x => x.title === title && x.author === author)) return;
      posts.push({ key: 'f' + posts.length, pid: pid || '', author, title, content, time: time || '', board: board || '', mine: !!mine, replies: [] });
    };
    const addReply = (author, title, content, time, mine, pid) => {
      const p = findPost(title, pid);
      if (!p || !author || !content) return;
      if (p.replies.some(r => r.author === author && r.content === content)) return;
      p.replies.push({ author, content, time: time || '', mine: !!mine });
    };
    for (const m of msgs) {
      const text = String(m.message || '');
      if (m.role === 'user') {
        let mt = text.match(/^【论坛发帖】(.+?)发布帖子《([^》]+)》[：:]([\s\S]*?)(?:【要求】[\s\S]*)?$/);
        if (mt) { addPost(mt[1].trim(), mt[2].trim(), mt[3].trim(), '刚刚', true, '', ''); continue; }
        mt = text.match(/^【论坛回帖】(.+?)回复《([^》]+)》[：:]([\s\S]*?)(?:【要求】[\s\S]*)?$/);
        if (mt) addReply(mt[1].trim(), mt[2].trim(), mt[3].trim(), '刚刚', true, '');
        continue;
      }
      if (m.role !== 'assistant') continue;

      const tagRe = /<(post|reply)\b((?:[^>"']|"[^"]*"|'[^']*')*?)\/?>/gi;
      let hit;
      while ((hit = tagRe.exec(text))) {
        const a = parseAttrs(hit[2]);
        if (hit[1].toLowerCase() === 'post') addPost(a.author, a.title, a.content, a.time, false, a.board, a.id);
        else addReply(a.author, a.title, a.content, a.time, false, a.post);
      }

      const re = /<FORUM>([\s\S]*?)<\/FORUM>/gi;
      let block;
      while ((block = re.exec(text))) {
        block[1].split('\n').forEach(line => {
          const p = line.trim().split(/[|｜]/).map(x => x.trim());
          if (p[0] === '帖' && p.length >= 4) addPost(p[1], p[2], p[3], p[4], false, '', '');
          else if (p[0] === '回' && p.length >= 4) addReply(p[1], p[2], p[3], p[4], false, '');
        });
      }
    }
    return posts.slice().reverse();
  }

  let cache = null;
  function snap() {
    if (cache) return cache;
    const msgs = getAll();
    let u = '我';
    for (const m of msgs) if (m.role === 'user' && m.name) u = m.name;
    const dm = parseDM(msgs);
    cache = {
      u,
      convos: dm.convos,
      seq: dm.seq,
      posts: parsePosts(msgs, u),
      market: parseMarket(msgs),
      forum: parseForum(msgs)
    };
    return cache;
  }

