      if (m.type === 'img') inner = isUrl(ct.trim()) ? '<img class="pq-img" referrerpolicy="no-referrer" src="' + esc(ct.trim()) + '">' : '<div class="pq-imgd">📷 ' + esc(ct) + '</div>';
      else if (m.type === 'voice') { inner = '<div class="pq-bub">🔊 ' + Math.max(1, Math.round(ct.length / 4)) + '″</div>'; tail = ct ? '<div class="pq-vt">' + esc(ct) + '</div>' : ''; }
