  /* ========== 主窗口 ========== */
  const win = d.createElement('div');
  win.id = 'pq-win';
  win.style.cssText = 'right:10px;top:' + Math.max(40, Math.round((VH - H) / 2)) + 'px;width:' + W + 'px;height:' + H + 'px;';
  M.appendChild(win);

  const vv = (window.top && window.top.visualViewport) || window.visualViewport;
  let kbSaved = null, kbEl = null;
  function fitKB() {
    if (!vv || !kbEl) return;
    const r = win.getBoundingClientRect();
    if (!kbSaved) kbSaved = { top: win.style.top, height: win.style.height };
    const maxBottom = vv.offsetTop + vv.height - 6;
    if (r.bottom > maxBottom) {
      let nt = maxBottom - r.height;
      if (nt < vv.offsetTop + 4) { nt = vv.offsetTop + 4; win.style.height = (maxBottom - nt) + 'px'; }
      win.style.top = nt + 'px';
    }
    const b = win.querySelector('.pq-body');
    if (b) b.scrollTop = b.scrollHeight;
  }
  function unfitKB() {
    if (kbSaved) { win.style.top = kbSaved.top; win.style.height = kbSaved.height || (H + 'px'); kbSaved = null; }
    kbEl = null;
  }
  if (vv) {
    const onVV = () => { if (kbEl && d.activeElement === kbEl) fitKB(); };
    on(vv, 'resize', onVV);
    on(vv, 'scroll', onVV);
  }
  function bindKB(el) {
    el.addEventListener('focus', () => { kbEl = el; setTimeout(fitKB, 300); });
    el.addEventListener('blur', () => setTimeout(() => { if (d.activeElement !== el) unfitKB(); }, 150));
  }

  function sendMarketRefresh() {
    const state = phoneState();
    const p = state.p || {};
    const city = p.city || '未知城市';
    const realm = p.realm || '凡人';
    const aura = state.aura != null ? state.aura : 5;

    slash('/send ' + (
      '【黑市刷新】当前城市：' + city +
      '；角色境界：' + realm +
      '；灵气浓度：' + aura +
      '；请生成3至6件符合当地生态的黑市商品。' +
      '必须使用<market id="" seller="" name="" type="" rank="" price="" stock="" eff="" desc="">格式。' +
      '商品应符合末法时代资源稀缺设定。'
    ) + ' | /trigger');
  }

  let forumKey = '';
  let forumComposing = false;
  let mkOpen = '';

  function toast(t) {
    const scr = win.querySelector('.pq-scr');
    if (!scr) return;
    const old = scr.querySelector('.pq-toast');
    if (old) old.remove();
    const el = d.createElement('div');
    el.className = 'pq-toast';
    el.textContent = t;
    scr.appendChild(el);
    setTimeout(() => { try { el.remove(); } catch (e) {} }, 1800);
  }

  function sendForumRefresh() {
    const state = phoneState();
    const city = state.p && state.p.city ? state.p.city : '未知城市';

    slash('/send ' + (
      '【论坛刷新】当前城市：' + city +
      '；请生成2至5条本地城市论坛帖子，每条一行：<post id="" board="" author="" title="" time="" content=""/>。' +
      '每条帖子可以附带0至3条回复，每条一行：<reply title="帖子标题" author="" time="" content=""/>。' +
      '内容可以是城市新闻、夜班见闻、旧货交易、异常目击或普通生活，不要直接揭露幕后真相。属性值里不要出现英文双引号。'
    ).replace(/\|/g, '\\|') + ' | /trigger');
  }

  function sendForumPost(title, text) {
    const u = snap().u;
    slash('/send ' + (
      '【论坛发帖】' + u + '发布帖子《' + title + '》：' + text +
      '【要求】请生成2至4条路人回复，每条一行：<reply title="' + title + '" author="" time="" content=""/>。' +
      '作者使用不同的网名，回复贴合帖子话题与当地氛围，不要直接揭露幕后真相。属性值里不要出现英文双引号。'
    ).replace(/\|/g, '\\|') + ' | /trigger');
  }

  function sendForumReply(title, text) {
    const u = snap().u;
    slash('/send ' + (
      '【论坛回帖】' + u + '回复《' + title + '》：' + text +
      '【要求】请生成1至3条新的回复，每条一行：<reply title="' + title + '" author="" time="" content=""/>。属性值里不要出现英文双引号。'
    ).replace(/\|/g, '\\|') + ' | /trigger');
  }

  function sendMarketAsk(item, q) {
    slash('/send ' + (
      '【黑市询价】商品id：' + item.id + '；商品名：' + item.name + '；当前标价：' + item.price + '；玩家询问：' + q +
      '【要求】请以卖家' + item.seller + '的口吻回答，输出一行：<market_reply id="' + item.id + '" text="卖家的回答"/>，text里不要出现英文双引号。' +
      '卖家可以松口降价、涨价或拒绝；如果价格变了，同时用同一个id重新输出这件商品的<market>标签。不要替玩家决定购买。'
    ).replace(/\|/g, '\\|') + ' | /trigger');
  }

  function sendMarketBuy(item) {
    slash('/send ' + (
      '【黑市购买】商品id：' + item.id +
      '；商品名：' + item.name +
      '；价格：' + item.price +
      '；请判断商品是否仍然存在、价格是否改变、玩家现金是否足够，以及卖家是否愿意交易。'
    ) + ' | /trigger');
  }

  function sendDM(target, list) {
    const u = snap().u;
    const arr = (Array.isArray(list) ? list : [list]).map(s => String(s).trim()).filter(Boolean);
    if (!arr.length) return;
    const cmds = arr.map(text => '/send ' + ('【微信】' + u + '回复' + target + '的消息：' + text).replace(/\|/g, '\\|'));
    slash(cmds.join(' | ') + ' | /trigger');
  }
  function sendPost(text, img) {
    const u = snap().u;
    slash('/send ' + ('【朋友圈】' + u + '发布动态：' + text + (img ? '【图片：' + img + '】' : '')).replace(/\|/g, '\\|') + ' | /trigger');
  }
  function sendComment(author, text) {
    const u = snap().u;
    slash('/send ' + ('【朋友圈】' + u + '评论' + (author === '我' ? u : author) + '的动态：' + text).replace(/\|/g, '\\|') + ' | /trigger');
  }

  function refreshPending() {
    const wrap = win.querySelector('.pq-pw');
    if (!wrap) return;
    let h = pending.map((t, i) => '<div class="pq-pd" data-act="pend-x" data-i="' + i + '"><span class="pq-pdx">×</span><div class="pq-pdb">' + esc(t) + '</div></div>').join('');
    if (pending.length) h += '<div class="pq-pdh">' + pending.length + ' 条待发 · 再点发送键送出</div>';
    wrap.innerHTML = h;
    const cnt = win.querySelector('.pq-cnt');
    if (cnt) { cnt.style.display = pending.length ? 'block' : 'none'; cnt.textContent = pending.length; }
    const b = win.querySelector('.pq-body');
    if (b) b.scrollTop = b.scrollHeight;
  }
  function bindChat() {
    const ip = win.querySelector('.pq-ip'), sd = win.querySelector('.pq-sd');
    if (!ip || !sd) return;
    const stash = () => {
      const v = ip.value.trim();
      if (!v) return false;
      pending.push(v);
      ip.value = '';
      refreshPending();
      return true;
    };
    const doSend = () => {
      const v = ip.value.trim();
      if (v) { pending.push(v); ip.value = ''; }
      if (!pending.length || !chatTarget) return;
      const list = pending.slice();
      pending = [];
      refreshPending();
      sendDM(chatTarget, list);
    };
    let tapTimer = null;
    sd.addEventListener('click', e => {
      e.preventDefault();
      if (tapTimer) { clearTimeout(tapTimer); tapTimer = null; doSend(); return; }
      if (!ip.value.trim()) { doSend(); return; }
      stash();
      sd.style.background = '#c8c8c8';
      tapTimer = setTimeout(() => { tapTimer = null; sd.style.background = '#1aad19'; ip.focus(); }, 320);
    });
    ip.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); stash(); } });
    refreshPending();
    const b = win.querySelector('.pq-body');
    if (b) b.scrollTop = b.scrollHeight;
  }
  function doComment() {
    const ip = win.querySelector('.pq-ip[data-k="cmt"]');
    const p = viewPosts.find(x => x.key === cmtKey);
    if (!ip || !p) return;
    const v = ip.value.trim();
    if (!v) return;
    cmtKey = '';
    sendComment(p.author, v);
    render();
  }

  function render(keep) {
    userAvCache = '';
    readVP();
    const saved = {};
    let focusK = '', st = 0;
    if (keep) {
      win.querySelectorAll('[data-k]').forEach(el => { const k = el.getAttribute('data-k'); saved[k] = el.value; if (d.activeElement === el) focusK = k; });
      const sc = win.querySelector('.pq-sc');
      if (sc) st = sc.scrollTop;
    }

    const onHome = isHome();
    let body;
    if (composing) body = renderCompose();
    else if (forumComposing) body = renderForumCompose();
    else if (chatTarget) body = renderChat(chatTarget);
    else if (tab === 'home') body = renderHome();
    else if (tab === 'forum') body = forumKey ? renderForumPost() : renderForum();
    else if (tab === 'msg') body = renderList();
    else if (tab === 'market') body = renderMarket();
    else body = renderMoments();
    win.innerHTML = '<div class="pq-scr' + (onHome ? ' pq-wp' : '') + '"' + (onHome && WALLPAPER ? ' style="' + urlCss(WALLPAPER) + '"' : '') + '><div class="pq-notch"></div>' + body + '<div class="pq-home" data-act="home"></div></div>';
    const fip = win.querySelector('.pq-ip[data-k="frp"]');
    if (fip) fip.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); doForumReply(); } });
    if (!keep && forumComposing) { const fta = win.querySelector('.pq-ta'); if (fta) setTimeout(() => fta.focus(), 200); }
    const mip = win.querySelector('.pq-ip[data-k="mkq"]');
    if (mip) mip.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); doMarketAsk(); } });
    const mtk = win.querySelector('.pq-mk-talk');
    if (mtk) mtk.scrollTop = mtk.scrollHeight;
    win.querySelectorAll('[data-k]').forEach(el => {
      const k = el.getAttribute('data-k');
      if (saved[k] != null) el.value = saved[k];
      bindKB(el);
    });
    const sc2 = win.querySelector('.pq-sc');
    if (sc2 && st) sc2.scrollTop = st;
    if (chatTarget && !composing) bindChat();
    const cip = win.querySelector('.pq-ip[data-k="cmt"]');
    if (cip) cip.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); doComment(); } });
    const target = focusK ? win.querySelector('[data-k="' + focusK + '"]') : null;
    if (target) { try { target.focus(); } catch (e) {} }
    else if (kbSaved) unfitKB();
    if (!keep && composing) { const ta = win.querySelector('.pq-ta'); if (ta) setTimeout(() => ta.focus(), 200); }
    if (!keep && cip) setTimeout(() => cip.focus(), 100);
  }

  function isHome() {
    return tab === 'home' && !composing && !forumComposing && !chatTarget;
  }
  function openApp(name) {
    pending = []; chatTarget = null; composing = false; forumComposing = false; forumKey = ''; cmtKey = ''; mkOpen = '';
    tab = name;
    render();
  }
  function goHome() {
    openApp('home');
  }
  function goBack() {
    if (mkOpen) { mkOpen = ''; render(); return; }
    pending = [];
    if (composing) composing = false;
    else if (forumComposing) forumComposing = false;
    else if (chatTarget) { chatTarget = null; tab = 'msg'; }
    else if (tab === 'forum' && forumKey) forumKey = '';
    else if (tab === 'pyq') { cmtKey = ''; tab = 'msg'; }
    else tab = 'home';
    render();
  }
  function doForumReply() {
    const ip = win.querySelector('.pq-ip[data-k="frp"]');
    const p = (snap().forum || []).find(x => x.key === forumKey);
    if (!ip || !p) return;
    const v = ip.value.trim();
    if (!v) return;
    ip.value = '';
    sendForumReply(p.title, v);
    toast('回复已发送');
  }
  function doMarketAsk() {
    const ip = win.querySelector('.pq-ip[data-k="mkq"]');
    const item = (snap().market || []).find(x => x.id === mkOpen);
    if (!ip || !item) return;
    const v = ip.value.trim();
    if (!v) { toast('先写点想问的'); return; }
    ip.value = '';
    sendMarketAsk(item, v);
    toast('已询价，等待卖家回复');
  }

  on(win, 'click', e => {
    const t = e.target.closest ? e.target.closest('[data-act]') : null;
    if (!t || !win.contains(t)) return;
    const a = t.getAttribute('data-act'), i = parseInt(t.getAttribute('data-i'), 10);
    if (a === 'noop') return;
    if (a === 'home') goHome();
    else if (a === 'back') goBack();
    else if (a === 'app') openApp(t.getAttribute('data-app'));
    else if (a === 'pyq') openApp('pyq');
    else if (a === 'forum-refresh') { sendForumRefresh(); toast('已请求刷新论坛'); }
    else if (a === 'market-refresh') { sendMarketRefresh(); toast('已请求刷新黑市'); }
    else if (a === 'market-ask') { mkOpen = t.getAttribute('data-id'); render(); }
    else if (a === 'mk-close') { mkOpen = ''; render(); }
    else if (a === 'mk-chip') {
      const ip = win.querySelector('.pq-ip[data-k="mkq"]');
      if (ip) { ip.value = t.getAttribute('data-q'); ip.focus(); }
    }
    else if (a === 'mk-ask-send') { doMarketAsk(); }
    else if (a === 'market-buy') {
      const id = t.getAttribute('data-id');
      const item = (snap().market || []).find(x => x.id === id);
      if (item) {
        mkOpen = '';
        sendMarketBuy(item);
        render();
        toast('已发出购买请求');
      }
    }
    else if (a === 'forum-open') { forumKey = t.getAttribute('data-key'); render(); }
    else if (a === 'forum-compose') { forumComposing = true; render(); }
    else if (a === 'forum-compose-x') { forumComposing = false; render(); }
    else if (a === 'forum-post') {
      const ti = win.querySelector('[data-k="ftt"]'), tx = win.querySelector('[data-k="ftx"]');
      const title = ti ? ti.value.trim().replace(/[《》]/g, '') : '', text = tx ? tx.value.trim() : '';
      if (!title || !text) { toast('标题和正文都要写'); return; }
      forumComposing = false;
      sendForumPost(title, text);
      render();
      toast('帖子已发出，等待回复');
    }
    else if (a === 'forum-reply-send') { doForumReply(); }
    else if (a === 'open') { pending = []; chatTarget = t.getAttribute('data-name'); render(); }
    else if (a === 'compose') { composing = true; render(); }
    else if (a === 'compose-x') { composing = false; render(); }
    else if (a === 'post') {
      const tx = win.querySelector('.pq-ta'), im = win.querySelector('.pq-ii');
      const text = tx ? tx.value.trim() : '', img = im ? im.value.trim() : '';
      if (!text && !img) return;
      composing = false;
      sendPost(text, img);
      render();
    }
    else if (a === 'like') { const p = viewPosts[i]; if (!p) return; if (myLikes.has(p.key)) myLikes.delete(p.key); else myLikes.add(p.key); render(true); }
    else if (a === 'cmt') { const p = viewPosts[i]; if (!p) return; cmtKey = (cmtKey === p.key) ? '' : p.key; render(true); }
    else if (a === 'cmt-x') { cmtKey = ''; render(true); }
    else if (a === 'cmt-send') { doComment(); }
    else if (a === 'pend-x') { pending.splice(i, 1); refreshPending(); }
  });

  let swipeStartX = 0;
  let swipeStartY = 0;

  on(win, 'touchstart', e => {
    if (!e.touches || !e.touches[0]) return;
    swipeStartX = e.touches[0].clientX;
    swipeStartY = e.touches[0].clientY;
  }, { passive: true });

  on(win, 'touchend', e => {
    if (!e.changedTouches || !e.changedTouches[0]) return;

    const dx = e.changedTouches[0].clientX - swipeStartX;
    const dy = e.changedTouches[0].clientY - swipeStartY;

    if (Math.abs(dx) < 80 || Math.abs(dx) < Math.abs(dy)) return;
    if (Math.abs(dx) !== -dx) return;

    pending = [];
    if (isHome()) { toggleApp(); return; }
    goBack();
  }, { passive: true });

  /* ========== 拖拽 ========== */
  let dragDx = 0, dragDy = 0, dragging = false;
  const inHandle = t => !!(t && t.closest && t.closest('.pq-sb,.pq-hd') && !t.closest('[data-act],input,textarea,button'));
  function onDragStart(x, y) {
    dragging = true;
    const r = win.getBoundingClientRect();
    dragDx = x - r.left; dragDy = y - r.top;
  }
  function onDragMove(x, y) {
    if (!dragging) return;
    win.style.left = Math.max(0, Math.min(x - dragDx, VW - win.offsetWidth)) + 'px';
    win.style.top = Math.max(0, Math.min(y - dragDy, VH - 60)) + 'px';
    win.style.right = 'auto';
  }
  const onDragEnd = () => { dragging = false; };
  on(win, 'mousedown', e => { if (!inHandle(e.target)) return; onDragStart(e.clientX, e.clientY); e.preventDefault(); });
  on(win, 'touchstart', e => { if (!inHandle(e.target)) return; const t = e.touches[0]; onDragStart(t.clientX, t.clientY); e.preventDefault(); }, { passive: false });
  on(d, 'mousemove', e => onDragMove(e.clientX, e.clientY));
  on(d, 'mouseup', onDragEnd);
  on(d, 'touchmove', e => { if (dragging) { const t = e.touches[0]; onDragMove(t.clientX, t.clientY); } }, { passive: true });
  on(d, 'touchend', onDragEnd);

  function toggleApp() {
    isOpen = !isOpen;

    if (isOpen) {
      readVP();
      W = Math.min(380, VW - 16);
      H = Math.min(620, VH - 80);

      win.style.width = W + 'px';
      win.style.height = H + 'px';
      win.style.display = 'flex';

      win.classList.remove('pq-in');
      void win.offsetWidth;
      win.classList.add('pq-in');

      render();
    } else {
      unfitKB();
      win.style.display = 'none';
      chatTarget = null;
      composing = false;
      forumComposing = false;
      forumKey = '';
      cmtKey = '';
      pending = [];
    }
  }
  window.__PQ_TOGGLE__ = toggleApp;

  /* ========== 酒馆事件 ========== */
  let renderTimer = null;
  function schedRender() {
    cache = null;
    clearTimeout(renderTimer);
    renderTimer = setTimeout(() => {
      if (isOpen) render(true);
    }, 150);
  }
  if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined') {
    [tavern_events.CHARACTER_MESSAGE_RENDERED, tavern_events.USER_MESSAGE_RENDERED, tavern_events.MESSAGE_SWIPED, tavern_events.MESSAGE_UPDATED, tavern_events.MESSAGE_DELETED, tavern_events.CHAT_CHANGED].filter(Boolean).forEach(ev => {
      try { const r = eventOn(ev, schedRender); offs.push(() => { try { if (r && r.stop) r.stop(); } catch (e) {} }); } catch (e) {}
    });
    try {
      const r = eventOn(tavern_events.CHAT_CHANGED, () => {
        for (const k in readMark) delete readMark[k];
        myLikes.clear();
        pending = []; chatTarget = null; composing = false; cmtKey = '';
      });
      offs.push(() => { try { if (r && r.stop) r.stop(); } catch (e) {} });
    } catch (e) {}
  }

  const clkT = setInterval(() => { const e = win.querySelector('.pq-clk'); if (e) e.textContent = clock(); }, 20000);
  function cleanup() {
    offs.splice(0).forEach(f => { try { f(); } catch (e) {} });
    clearInterval(clkT);
    clearTimeout(renderTimer);
    [win, styleEl].forEach(e => { try { e.remove(); } catch (er) {} });
    try { if (d.__pqOff === cleanup) delete d.__pqOff; } catch (e) {}
  }
  d.__pqOff = cleanup;
  on(window, 'pagehide', cleanup);
})();

try {
  if (typeof getButtonEvent === 'function') {
    eventOn(getButtonEvent('手机'), () => {
      if (window.__PQ_TOGGLE__) window.__PQ_TOGGLE__();
    });
  }
} catch (e) {}
